import React from 'react';

import PageLoader from '@components/PageLoader/index';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';

import Sticker from './components/Sticker';
import { filterHikersByDate } from './index';
import { IProductForPrint } from './mapper';
import { getHikingDataAsync } from '../../../@services/hiking.service';
import { getHikingProductsForPrint } from '../../../@services/hikingMenu.service';
import { IHikingData } from '../../../@types/hiking.types';

interface IStickersBuiltInProps {
  id_hiking: number;
  id_user?: number;
  date?: string;
  id_product?: number;
}

const StickersBuiltIn: React.FC<IStickersBuiltInProps> = (props) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [err, setErr] = React.useState<Error>();
  const [stickers, setStickers] = React.useState<IProductForPrint[]>([]);

  React.useEffect(() => {
    getHikingDataAsync(props.id_hiking).then(setHikingData);
    getHikingProductsForPrint(props.id_hiking, props)
      .then(setStickers)
      .catch(setErr)
      .finally(() => setIsLoading(false));
  }, [props.id_hiking]);

  if (isLoading || !hikingData) {
    return <PageLoader />;
  }
  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err?.message}</PohAlert>;
  }

  return (
    <section style={{ columns: 2 }}>
      {stickers.map((st) => {
        const hikersForAct = hikingData.hikers.filter(filterHikersByDate(st.date));
        return (
          <Sticker
            data={st}
            key={`${st.date}${st.recipeName}${st.idProduct}`}
            hikersCount={hikersForAct.length}
            hikersMaxCount={hikingData.hikers.length}
          />
        );
      })}
    </section>
  );
};

export default StickersBuiltIn;
