import React from 'react';

import ArrowRightShort from '@pohodnik/icons/svg/Arrows/ArrowRightShort';

import { getHikingAccessGroupAsync } from '@apps/Hiking/@services/hikingRules.service';
import { HikingAccessGroup } from '@apps/Hiking/@types/hiking.rules';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohList from '@ui-kit/List';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import { editHikingMenuProductsReplaces } from './HikingMenuProductsReplaceEditModal';
import {
  deleteHikingMenuProductsReplace,
  getHikingMenuProductsReplaces,
} from '../../../@services/hikingMenuReplaces.service';
import { IHikingMenuProductReplace } from '../../../@types/hikingMenuReplaces.types';

interface IHikingMenuProductsReplacesProps {
  id_hiking: number;
  disabled?: boolean;
}

const HikingMenuProductsReplaces: React.FC<IHikingMenuProductsReplacesProps> = ({
  id_hiking,
  disabled,
}) => {
  const [data, setData] = React.useState<IHikingMenuProductReplace[]>([]);
  const [canEdit, setCanEdit] = React.useState(false);
  const [isLoading, setIsLoading] = React.useState(true);

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const hmpr = await getHikingMenuProductsReplaces(id_hiking);
        setData(hmpr);

        const accessGroup = await getHikingAccessGroupAsync(id_hiking);
        setCanEdit(
          [
            HikingAccessGroup.Full,
            HikingAccessGroup.All,
            HikingAccessGroup.Boss,
            HikingAccessGroup.Kitchen,
          ].includes(accessGroup),
        );
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [id_hiking]);

  const handleAdd = async () => {
    const newReplace = await editHikingMenuProductsReplaces(id_hiking);
    setData((cur) => [...cur, newReplace]);
  };
  const handleEdit = async (pr: IHikingMenuProductReplace) => {
    const newReplace = await editHikingMenuProductsReplaces(id_hiking, pr);
    setData((cur) => cur.map((r) => (r.id === pr.id ? newReplace : r)));
  };
  const handleDelete = async (pr: IHikingMenuProductReplace) => {
    if (await confirmModal2(`Удалить замену для продукта: ${pr.sourceProduct.name}`)) {
      await deleteHikingMenuProductsReplace({ id_hiking, id: pr.id });
      setData((cur) => cur.filter((r) => r.id !== pr.id));
    }
  };

  if (isLoading) return null;

  return (
    <section>
      <header className="d-flex">
        <h5 className="m-0">Замены продуктов</h5>
        <aside className="ms-auto">
          {!disabled && canEdit && (
            <PohButton size={ButtonSize.Small} onClick={handleAdd}>
              Добавить
            </PohButton>
          )}
        </aside>
      </header>
      <PohList
        data={data.map((pr) => {
          return {
            key: pr.id,
            children: (
              <div className="d-flex align-items-center">
                <span>{pr.sourceProduct.name}</span>
                &nbsp;
                <ArrowRightShort />
                &nbsp;
                <span>{pr.targetProduct.name}</span>
                &nbsp;
                <strong className="text-danger">&times;&thinsp;{pr.rate.toLocaleString()}</strong>
                &nbsp; &nbsp;
                <em>
                  <small className="tex-muted">{pr.comment}</small>
                </em>
                <span className="ms-auto">
                  {!disabled && canEdit && (
                    <PohButton
                      size={ButtonSize.Small}
                      icon={IconsEnum.trash}
                      onClick={() => handleDelete(pr)}
                    />
                  )}
                  {!disabled && canEdit && (
                    <PohButton
                      size={ButtonSize.Small}
                      icon={IconsEnum.edit}
                      onClick={() => handleEdit(pr)}
                    />
                  )}
                </span>
              </div>
            ),
          };
        })}
      />
    </section>
  );
};

export default HikingMenuProductsReplaces;
