/* eslint-disable @typescript-eslint/ban-ts-comment */
import React from 'react';

import ChevronBarContract from '@pohodnik/icons/svg/Chevrons/ChevronBarContract';
import ChevronBarExpand from '@pohodnik/icons/svg/Chevrons/ChevronBarExpand';
import clsx from 'clsx';
import Chart from 'react-google-charts';

import PageLoader from '@components/PageLoader/index';
import { stringToColour } from '@helpers/colorsizeStringHelper';
import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import PohProgress from '@ui-kit/Progress';

import { getHikingMenuWeightSummary } from './hikingMenuSummary.helper';
import style from './style.module.less';
import { IHiker } from '../../../../../@types/hiking.types';
import {
  IHikingMenuExtendedProduct,
  IHikingMenuFood,
} from '../../../../../@types/hikingMenu.types';
import { getShortName } from '../../helper';

interface ISummaryPanelProps {
  foods: IHikingMenuFood[];
  products: IHikingMenuExtendedProduct[];
  hikers: IHiker[];
  floatLoads?: boolean;
}

const SummaryPanel: React.FC<ISummaryPanelProps> = ({
  foods,
  products,
  hikers,
  floatLoads = true,
}) => {
  const [isFloatingChart, setIsFloatingChart] = React.useState<boolean>(
    JSON.parse(localStorage.getItem('floatChart') ?? 'false'),
  );

  React.useEffect(() => {
    localStorage.setItem('floatChart', isFloatingChart.toString());
  }, [isFloatingChart]);

  React.useEffect(() => {
    const handleKeyPress = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.code === 'KeyX') {
        setIsFloatingChart((c) => !c);
      }
    };

    window.addEventListener('keypress', handleKeyPress);
    return () => window.removeEventListener('keypress', handleKeyPress);
  }, []);

  const {
    userTotalAggregation,
    dateUserWeightAggregation,
    maxUserLoads: defaultMaxUserLoads,
  } = getHikingMenuWeightSummary(foods, products, hikers.length);

  const maxUserLoads = { ...defaultMaxUserLoads };

  const total = Object.values(userTotalAggregation).reduce(
    (sum, { forcedAmount, amount }) => sum + round(forcedAmount + amount),
    0,
  );

  const headers: string[] = [
    'Дата',
    ...Object.keys(userTotalAggregation).reduce<string[]>(
      (acc, val) => acc.concat(getShortName(userTotalAggregation[+val].user?.name || 'Кто-то', 1)),
      [],
    ),
  ];

  const chartData = Object.keys(dateUserWeightAggregation)
    .sort()
    .map((dateStr) => [
      new Date(dateStr),
      ...Object.keys(userTotalAggregation).map((uid) => {
        // @ts-ignore
        maxUserLoads[+uid] -= (dateUserWeightAggregation[dateStr]?.[uid] || 0) * hikers.length;
        // @ts-ignore
        return maxUserLoads[uid] / 1000;
      }),
    ]);

  const chartArr = [headers, ...chartData];

  const colors = [...headers.slice(1)].map((s) => stringToColour(s));

  return (
    <footer className={clsx(style.infoPanel)} title={(total * hikers.length).toString()}>
      <h4>Загрузка участников</h4>
      {Object.values(userTotalAggregation).map(({ user, forcedAmount, amount }) => {
        const curWeight = (forcedAmount + amount) * hikers.length;
        const pct = round((curWeight / total) * 100, 0);
        return (
          <div
            key={user?.id}
            title={`${round(forcedAmount)}\n${round(amount)}`}
            className="py-2 px-3 badge-light d-flex border-bottom align-items-center"
          >
            <PohAva src={user?.photo} alt={user?.name} />
            <div className="ps-2 flex-grow-1">
              {user?.name} {round((forcedAmount + amount) * hikers.length)}
              <PohProgress value={pct}>
                {pct}% ({round(curWeight, 0)}/{round(total, 0)})
              </PohProgress>
            </div>
          </div>
        );
      })}

      {floatLoads && (
        <aside style={{ position: 'fixed', bottom: isFloatingChart ? 420 : 0, left: 0 }}>
          {Object.values(userTotalAggregation).map(({ user, forcedAmount, amount }) => {
            const curWeight = (forcedAmount + amount) * hikers.length;
            const pct = round((curWeight / total) * 100, 0);
            return (
              <div
                key={user?.id}
                title={`${round(forcedAmount)}\n${round(amount)}`}
                className="border-bottom d-flex align-items-center"
              >
                <div
                  className="ps-2 pe-2 d-flex align-items-center justify-content-center"
                  style={{ width: 40, height: 40 }}
                >
                  <div
                    className="position-relative me-2 pe-2 ms-2"
                    style={{
                      borderRight: '3px solid transparent',
                      borderColor: stringToColour(getShortName(user?.name ?? '', 1)),
                    }}
                  >
                    <PohAva
                      src={user?.photo}
                      alt={user?.name}
                      width={24}
                      title={getShortName(user?.name ?? '', 1)}
                    />
                  </div>
                </div>
                <small>
                  {pct}%
                  <br />
                  <small>
                    ({round(curWeight / 1000, 1)}&nbsp;/&nbsp;{round(total / 1000, 1)})
                  </small>
                </small>
              </div>
            );
          })}
        </aside>
      )}
      {chartArr.length > 2 && (
        <aside className={clsx(isFloatingChart && style.floatingChart)}>
          <header className="d-flex align-items-center justify-content-between">
            {!isFloatingChart && <h3 className="mt-3">График убывания загрузки</h3>}
            <PohButton
              onClick={() => setIsFloatingChart((c) => !c)}
              icon={true}
              size={ButtonSize.Small}
              title="Toggle: Ctrl + Shift + X"
            >
              {isFloatingChart ? <ChevronBarExpand /> : <ChevronBarContract />}
            </PohButton>
          </header>
          <Chart
            chartLanguage="ru"
            chartType="LineChart"
            loader={<PageLoader />}
            data={chartArr}
            options={{
              height: isFloatingChart ? 400 : 400,
              chartArea: {
                width: isFloatingChart ? '95%' : '90%',
                height: isFloatingChart ? '70%' : '80%',
              },
              //intervals: { style: 'sticks' },
              // legend: 'none',
              legend: isFloatingChart ? 'none' : { position: 'bottom', alignment: 'end' },
              crosshair: {
                color: 'lime',
                trigger: 'selection',
              },
              colors,
              smoothLine: true,
              hAxis: { format: 'd.MM\u2008HH', gridlines: { count: 3 } },
              vAxis: {
                format: 'short',
                viewWindowMode: 'explicit',
                viewWindow: {
                  min: 0,
                },
              },

              //series
            }}
          />
        </aside>
      )}
      {isFloatingChart && <div style={{ height: 200 }}>&nbsp;</div>}
    </footer>
  );
};

export default SummaryPanel;
