/* eslint-disable @typescript-eslint/ban-ts-comment */
import React, { useContext } from 'react';

import Reception3 from '@pohodnik/icons/svg/Communication/Reception3';
import CalendarRange from '@pohodnik/icons/svg/DateTime/CalendarRange';
import Printer from '@pohodnik/icons/svg/Devices/Printer';
import Grid3X3 from '@pohodnik/icons/svg/Layout/Grid3X3';
import PersonFill from '@pohodnik/icons/svg/People/PersonFill';
import ExclamationTriangle from '@pohodnik/icons/svg/Signs/ExclamationTriangle';
import { useNavigate } from 'react-router-dom';

import { showScheduleModal } from '@apps/Hiking/schedule/components/ScheduleModal/scheduleModalHelper';
import { selectRecipeAsync } from '@apps/Recipes/components/RecipeSelect/recipeSelectHelper';
import { selectHikerAsync } from '@components/HikerSelector/hikerSelectHelper';
import PageLoader from '@components/PageLoader/index';
import { declOfNum } from '@helpers/formatHelper';
import { handleApiError } from '@helpers/httpClient';
import { round } from '@helpers/mathHelper';
import { open } from '@helpers/navigationHelper';
import notificationHelper, { err, success, warn } from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import Breadcrumb from '@ui-kit/Breadcrumb/index';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohDropdown from '@ui-kit/Dropdown';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row/index';
import PohList from '@ui-kit/List';
import { confirmModal, showModal } from '@ui-kit/Modal/index';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import DayFullHeader from './components/DayFullHeader';
import DutyModal from './components/DutyModal';
import FoodActCard from './components/FoodActCard';
import HikingMenuItem from './components/HikingMenuItem';
import { IProductForPrint } from './components/ProductsMatrix';
import RecipesUsages from './components/RecipeUsagesModal';
import SummaryPanel from './components/SummaryPanel';
import { AuthContext } from '../../../../../contexts/AuthContext';
import { getRecipeByIdAsync } from '../../../../Recipes/@services/recipes.service';
import { includeActInfo } from '../../../@mappers/hikingMenu.mapper';
import { getHikingDataAsync, getHikingMembersAllergies } from '../../../@services/hiking.service';
import { getHikingDuty } from '../../../@services/hikingDuty.service';
import {
  addFoodAsync,
  deleteFoodByIdAsync,
  getFoodAsync,
  getHikingMenuActs,
  getHikingMenuProductsAsync,
  productForceAddAsync,
  productForceDelAsync,
  saveFoodPatchAsync,
  saveFoodPatchByIdAsync,
} from '../../../@services/hikingMenu.service';
import {
  confirmHikingMenuSaveAsync,
  getHikingMenuSavesAsync,
} from '../../../@services/hikingMenuSaves.service';
import { getHikingRecipes } from '../../../@services/hikingRecipes.service';
import { getHikingAccessGroupAsync } from '../../../@services/hikingRules.service';
import { IHikingDuty, IHikingMenuSave, IHikingRecipe } from '../../../@types/hiking.baseTypes';
import { HikingAccessGroup } from '../../../@types/hiking.rules';
import { IHikingData, IHikingMemberAllergy } from '../../../@types/hiking.types';
import {
  IHikingMenuActsByDays,
  IHikingMenuExtendedProduct,
  IHikingMenuFood,
  IHikingMenuFoodWithAct,
} from '../../../@types/hikingMenu.types';
import StickersBuiltIn from '../HikingMenuPrintStickers/StickersBuiltIn';
import HikingMenuProductsReplaces from '../HikingMenuProductsReplaces/HikingMenuProductsReplaces';
import HikingMenuSaves from '../HikingMenuSaves';

interface IHikingMenuProps {
  id_hiking: number;
}

const HikingMenu: React.FC<IHikingMenuProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);

  const [daysActs, setDaysActs] = React.useState<IHikingMenuActsByDays[]>([]);
  const [food, setFood] = React.useState<IHikingMenuFoodWithAct[]>([]);
  const [products, setProducts] = React.useState<IHikingMenuExtendedProduct[]>([]);
  const [duty, setDuty] = React.useState<IHikingDuty[]>([]);
  const [saves, setSaves] = React.useState<IHikingMenuSave[]>([]);
  const [hikingRecipes, setHikingRecipes] = React.useState<IHikingRecipe[]>([]);
  const [allergies, setAllergies] = React.useState<IHikingMemberAllergy[]>([]);
  const [actualKey, setActualKey] = React.useState<string>('');
  const [accessGroup, setAccessGroup] = React.useState<HikingAccessGroup>(
    HikingAccessGroup.Readonly,
  );

  const navigate = useNavigate();

  const [isLoading, setIsLoading] = React.useState(false);

  const authContext = useContext(AuthContext);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const hd = await getHikingDataAsync(id_hiking);
        setHikingData(hd);

        const hda = await getHikingMenuActs(id_hiking);
        setDaysActs(hda);

        const hf = await getFoodAsync({ id_hiking });
        const hfWithActs = hf.map(includeActInfo(hda));
        setFood(hfWithActs);

        const pdts = await getHikingMenuProductsAsync(id_hiking);
        setProducts(pdts);

        const dts = await getHikingDuty(id_hiking);
        setDuty(dts);

        const agd = await getHikingAccessGroupAsync(id_hiking);
        setAccessGroup(agd);

        const svs = await getHikingMenuSavesAsync(id_hiking);
        setSaves(svs);

        const hrc = await getHikingRecipes(id_hiking);
        setHikingRecipes(hrc);

        const ars = await getHikingMembersAllergies(id_hiking);
        setAllergies(ars);
      } catch (e1) {
        console.error(e1);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id_hiking, actualKey]);

  const recipesMetaMap = React.useMemo<Record<number, Record<string, any>>>(() => {
    return food.reduce<Record<number, Record<string, any>>>((acc, val) => {
      if (!acc[val.id_recipe]) {
        acc[val.id_recipe] = { usagesCount: 0, name: val.name };
      }
      acc[val.id_recipe]['usagesCount']++;
      return acc;
    }, {});
  }, [food]);

  const allergyProducts = React.useMemo(() => {
    return products.reduce<Record<number, IHikingMemberAllergy[]>>((acc, p) => {
      const productAllergies = allergies.filter((a) => a.id_product === p.id);
      if (productAllergies.length) {
        acc[p.id] = productAllergies;
      }
      return acc;
    }, {});
  }, [products, allergies]);

  if (isLoading || !hikingData) {
    return <PageLoader />;
  }

  const handleAddFoodToAct = async ({
    date,
    id_act,
    forceAll = false,
  }: {
    date: Date;
    id_act: number;
    forceAll?: boolean;
    multiMode?: boolean;
  }) => {
    try {
      if (
        !(hikingRecipes.length > 0) &&
        (await confirmModal2('Будет удобнее если настроить список рецептов приемлемых для похода'))
      )
        return navigate(`/hiking/${id_hiking}/menu/dishes`);
      const selectedRecipe = await selectRecipeAsync(
        forceAll ? undefined : { id_act, for_hiking: id_hiking },
        recipesMetaMap,
      );
      const addedHikingFoodId = await addFoodAsync({
        id_recipe: selectedRecipe.id,
        id_act,
        id_hiking,
        date,
      }).then<number>(handleApiError);
      const recipe = await getRecipeByIdAsync(selectedRecipe.id);

      success('Добавлено');

      const newHikingFood: IHikingMenuFood = {
        ...recipe,
        id: addedHikingFoodId,
        date,
        id_act: id_act,
        correction: 1,
        text: '',
        proteins: recipe.protein,
        fats: recipe.fat,
        id_recipe: recipe.id,
        carbs: recipe.carbs,
        assigneeUser: null,
        confirmUser: null,
        confirmDate: null,
      };

      setFood((curFood) => curFood.concat(includeActInfo(daysActs)(newHikingFood)));
    } catch (e) {
      notificationHelper.error((e as Error).message);
    }
  };
  const handleConfirmFood = async (hFood: IHikingMenuFoodWithAct) => {
    try {
      await saveFoodPatchAsync({ id_hiking, id: hFood.id, confirm: !hFood.confirmDate }).then(
        handleApiError,
      );
      setFood((curFood) =>
        curFood.map((x) => {
          // @ts-ignore
          const isTarget = hFood.id === x.id;
          if (isTarget && authContext.user) {
            return {
              ...x,
              confirmDate: hFood.confirmDate ? null : new Date(),
              confirmUser: hFood.confirmUser
                ? null
                : [authContext.user.name, authContext.user.surname].join(' '),
            };
          }

          return x;
        }),
      );
      success(
        !hFood.confirmDate
          ? `Утверждено: ${[authContext.user?.name, authContext.user?.surname].join(' ')}`
          : `Утверждение отменено`,
      );
    } catch (e) {
      notificationHelper.error((e as Error).message);
    }
  };
  const handleAssignToHiker = async (patch: any) => {
    try {
      const user = await selectHikerAsync(id_hiking, { withMe: true });
      await saveFoodPatchAsync({ assignee: user.idUser, id_hiking, ...patch }).then(handleApiError);
      setFood((curFood) =>
        curFood.map((x) => {
          // @ts-ignore
          const isTarget = Object.keys(patch).every((k: keyof IHikingMenuFoodWithAct) =>
            x[k] instanceof Date
              ? x[k].toISOString().substr(0, 10) === patch[k]
              : x[k] === patch[k],
          );
          if (isTarget) {
            return {
              ...x,
              assigneeUser: {
                id: user.idUser,
                name: [user.name, user.surname].join(' '),
                photo: user.photo['50'],
              },
            };
          }

          return x;
        }),
      );
      success(`Назначено: ${[user.name, user.surname].join(' ')}`);
    } catch (e) {
      notificationHelper.error((e as Error).message);
    }
  };
  const handleAssignReset = (patch: any) => {
    try {
      saveFoodPatchAsync({ assignee: 'NULL', id_hiking, ...patch })
        .then(handleApiError)
        .then(() => {
          setFood((curFood) =>
            curFood.map((x) => {
              // @ts-ignore
              const isTarget = Object.keys(patch).every((k: keyof IHikingMenuFoodWithAct) =>
                x[k] instanceof Date
                  ? x[k].toISOString().substr(0, 10) === patch[k]
                  : x[k] === patch[k],
              );

              if (isTarget) {
                return {
                  ...x,
                  assigneeUser: null,
                };
              }

              return x;
            }),
          );
          success('Назначение сброшено');
        });
    } catch (e) {
      notificationHelper.error((e as Error).message);
    }
  };

  const handleSaveConfirm =
    accessGroup !== HikingAccessGroup.Boss
      ? undefined
      : async (save: IHikingMenuSave) => {
          const pr = prompt(
            `Для ${save.confirmDate ? 'отмены' : ''} утверждения сборки меня «${save.name}» введите название похода\n(в точности как в оригинале)`,
          );
          if (pr !== hikingData.name) {
            err('Галя, у нас Отмена');
            warn('А вы попробуйте еще раз');
            return;
          }

          try {
            await confirmHikingMenuSaveAsync(id_hiking, save.id, !save.confirmDate).then(
              handleApiError,
            );
            setSaves((cur) => {
              return cur.map((c) => {
                return c.id !== save.id
                  ? c
                  : ({
                      ...c,
                      confirmUser:
                        save.confirmDate || !authContext.user?.id
                          ? null
                          : authContext.user.id.toString(),
                      confirmDate: save.confirmDate ? null : new Date(),
                    } satisfies IHikingMenuSave);
              });
            });
            success(`${save.confirmDate ? 'Отменено' : 'Утверждено'} «${save.name}»`);
          } catch (e) {
            notificationHelper.error((e as Error).message);
          }
        };

  const productsForPrint: Record<number, IProductForPrint> = {};
  let totalAmount = 0;

  const incRecipesUsages: Record<number, number> = {};

  const hasConfirmed = saves.some((d) => d.confirmDate);

  const disabled =
    hasConfirmed ||
    ![
      HikingAccessGroup.Boss,
      HikingAccessGroup.All,
      HikingAccessGroup.Full,
      HikingAccessGroup.Kitchen,
    ].includes(accessGroup);

  const isBoss = accessGroup === HikingAccessGroup.Boss;

  return (
    <>
      <PohContainer>
        <Breadcrumb
          data={[
            { href: '/hiking', text: 'Походы' },
            { href: `/hiking/${id_hiking}`, text: hikingData.name },
            { href: `/hiking/${id_hiking}/menu`, text: 'Меню похода', active: true },
          ]}
        />
        <header className="d-flex justify-content-between align-items-start w-100">
          <h3 className="mb-3">Меню похода &laquo;{hikingData.name}&raquo;</h3>

          <div>
            <PohDropdown
              menu={[
                <a
                  key="printStickers111"
                  className="dropdown-item"
                  href={`/hiking/${id_hiking}/menu/print1`}
                  target="_blank"
                  rel="noreferrer"
                >
                  Приёмы пищи
                </a>,
                <a
                  key="printStickers"
                  className="dropdown-item"
                  href={`/hiking/${id_hiking}/menu/stickers`}
                  target="_blank"
                  rel="noreferrer"
                >
                  Наклейки
                </a>,
              ]}
            >
              <PohButton icon={true}>
                <Printer />
              </PohButton>
            </PohDropdown>
          </div>
        </header>

        {!hasConfirmed && (
          <PohAlert variant={AlertVariant.Warning}>
            <ExclamationTriangle /> &nbsp; Меню не утверждено и может поменяться.
          </PohAlert>
        )}
        <HikingMenuSaves
          onApply={() => setActualKey(new Date().toISOString())}
          id_hiking={id_hiking}
          disabled={disabled}
          saves={saves}
          onConfirm={handleSaveConfirm}
        />

        {!hasConfirmed && (
          <div className="d-flex align-items-center justify-content-between my-2">
            {hikingRecipes.length > 0 ? (
              <span className="text-info">
                Для похода {declOfNum(hikingRecipes.length, ['настроен', 'настроено', 'настроены'])}{' '}
                {hikingRecipes.length}{' '}
                {declOfNum(hikingRecipes.length, ['рецепт', 'рецепта', 'рецептов'])}
              </span>
            ) : (
              <span className="text-warning">Настройте список рецептов, приемлемых для похода</span>
            )}
            <PohButton
              size={ButtonSize.Small}
              variant={hikingRecipes.length > 0 ? ButtonVariant.Light : ButtonVariant.Primary}
              onClick={() => navigate(`/hiking/${id_hiking}/menu/dishes`)}
              disabled={disabled}
            >
              Настроить список рецептов
            </PohButton>
          </div>
        )}

        {daysActs?.length > 0 &&
          daysActs.map((day, ind) => {
            const fact = food.filter(
              (x) => x.date.toLocaleDateString() === day.date.toLocaleDateString(),
            );
            const showDaySchedule = () =>
              showScheduleModal(
                +hikingData.id,
                day.date,
                `Расписание на ${day.date.toLocaleDateString()}`,
              );

            return (
              <div key={day.date.toString()} className="mt-3">
                <DayFullHeader
                  id_hiking={id_hiking}
                  day={day}
                  food={fact}
                  dayNumber={ind + 1}
                  additional={duty
                    .filter((d) => d.date.toLocaleDateString() === day.date.toLocaleDateString())
                    .map((d) => {
                      const hiker = hikingData?.hikers.find((h) => h.idUser === d.id_user);
                      if (!hiker) {
                        return null;
                      }
                      return (
                        <span
                          title={`Дежурство: ${[hiker.name, hiker.surname].join(' ')}`}
                          key={d.id_user}
                        >
                          <PohAva
                            width={24}
                            src={hiker.photo['50']}
                            alt={hiker.name + '' + hiker.surname}
                            style={{ opacity: 0.6 }}
                          />
                        </span>
                      );
                    })}
                />
                <PohRow>
                  {day.acts.map((act, _index, allActsInDay) => {
                    //const needKkalDayAct = act.kkalCurrent || act.kkalTarget || 0;
                    const actFood = food.filter(
                      (x) =>
                        x.date.toLocaleDateString() === day.date.toLocaleDateString() &&
                        x.id_act === act.id,
                    );

                    const targetDate = act.start;
                    const filteredHikers = hikingData.hikers.filter((h) => {
                      let byStartDate = true;
                      let byFinishDate = true;
                      if (h.dateFrom) {
                        byStartDate = h.dateFrom <= targetDate;
                      }

                      if (h.dateTo) {
                        byFinishDate = h.dateTo >= targetDate;
                      }

                      return byStartDate && byFinishDate;
                    });

                    return (
                      <PohCol
                        key={`${day.date.toString()}${act.id}`}
                        sm={Math.floor(12 / allActsInDay.length)}
                      >
                        <FoodActCard
                          act={act}
                          actFood={actFood}
                          onHeaderDoubleClick={() => {
                            handleAssignToHiker({
                              date: day.date.toISOString().substr(0, 10),
                              id_act: +act.id,
                            }).catch(err);
                          }}
                          headerAdditional={
                            hikingData.hikers.length > filteredHikers.length && (
                              <small
                                className="text-danger"
                                title={filteredHikers
                                  .map(
                                    (h) =>
                                      `${h.surname} ${h.name} ${[h.dateFrom || 'start', h.dateTo || 'finish'].join(' - ')}`,
                                  )
                                  .join('\n')}
                              >
                                &nbsp;{filteredHikers.length}/{hikingData.hikers.length}
                              </small>
                            )
                          }
                          bottomMenuActions={{
                            'Расписание на этот день': showDaySchedule,
                            [`Назначить весь ${act.name.toLowerCase()} участнику`]: () => {
                              handleAssignToHiker({
                                date: day.date.toISOString().substr(0, 10),
                                id_act: act.id,
                              });
                            },
                            ['Сбросить назначение участнику']: () =>
                              handleAssignReset({
                                date: day.date.toISOString().substring(0, 10),
                                id_act: +act.id,
                              }),
                          }}
                          onFooterButtonClick={(e) => {
                            handleAddFoodToAct({
                              date: day.date,
                              id_act: act.id,
                              forceAll: e.ctrlKey || e.altKey,
                            });
                          }}
                          disabled={disabled}
                        >
                          {!actFood.length && <Empty height={100}>Пока нету...</Empty>}
                          {actFood.length > 0 && (
                            <PohList
                              flush
                              data={actFood.map((foo) => {
                                if (!incRecipesUsages[foo.id_recipe]) {
                                  incRecipesUsages[foo.id_recipe] = 0;
                                }
                                incRecipesUsages[foo.id_recipe]++;

                                return {
                                  key: foo.id,
                                  className: 'py-2',
                                  content: (
                                    <HikingMenuItem
                                      onChange={(patch) => {
                                        if (patch.correction) {
                                          saveFoodPatchByIdAsync(foo.id, {
                                            id_hiking,
                                            сorrection_coeff_pct: round(patch.correction * 100),
                                          })
                                            .then(() => {
                                              setFood((curFood) =>
                                                curFood.map((x) =>
                                                  x.id === foo.id ? { ...x, ...patch } : x,
                                                ),
                                              );
                                            })
                                            .catch(err);
                                        }
                                      }}
                                      onDelete={() => {
                                        deleteFoodByIdAsync(foo.id)
                                          .then(() => {
                                            success('Удалено');
                                            setFood((curFood) =>
                                              curFood.filter((x) => x.id !== foo.id),
                                            );
                                          })
                                          .catch(err);
                                      }}
                                      onSetAssignee={() => handleAssignToHiker({ id: foo.id })}
                                      onResetAssignee={() => handleAssignReset({ id: foo.id })}
                                      count={incRecipesUsages[foo.id_recipe]}
                                      data={foo}
                                      disabled={disabled}
                                      onConfirm={
                                        isBoss
                                          ? () => {
                                              handleConfirmFood(foo);
                                            }
                                          : undefined
                                      }
                                    />
                                  ),
                                };
                              })}
                            />
                          )}
                        </FoodActCard>
                      </PohCol>
                    );
                  })}
                </PohRow>
              </div>
            );
          })}
        <section className="mt-4">
          <HikingMenuProductsReplaces id_hiking={id_hiking} disabled={disabled} />
        </section>
        <section className="mt-4">
          <h2>Продукты</h2>
          {products?.length > 0 && (
            <table className="table table-bordered table-striped table-hover table-condensed table-sm">
              <thead>
                <tr>
                  <th>Продукт</th>
                  <th>Масса г./чел.</th>
                  <th>Масса г./груп.</th>
                </tr>
              </thead>
              <tbody>
                {products.map((product) => {
                  const handleAssign = async (e: React.MouseEvent<HTMLDivElement>) => {
                    if (disabled) {
                      return;
                    }

                    e.preventDefault();
                    if (product?.idForce) {
                      const isOk = await confirmModal('Удалить назначение продукта?');
                      isOk && (await productForceDelAsync(product.idForce));
                      setProducts((curPr) =>
                        curPr.map((x) => {
                          if (x.id === product.id) {
                            return {
                              ...x,
                              id_force: null,
                              forcedUser: null,
                            };
                          }

                          return x;
                        }),
                      );
                      success('Сброшено');
                    } else {
                      const user = await selectHikerAsync(id_hiking, { withMe: true });
                      const forceId = await productForceAddAsync({
                        id_hiking,
                        id_user: user.idUser,
                        id_product: product.id,
                      });

                      setProducts((curPr) =>
                        curPr.map((x) => {
                          if (x.id === product.id) {
                            return {
                              ...x,
                              id_force: forceId,
                              forcedUser: {
                                id: user.idUser,
                                name: [user.name, user.surname].join(' '),
                                photo: user.photo['50'],
                              },
                            };
                          }

                          return x;
                        }),
                      );
                      success(`Назначено ${[user.name, user.surname].join(' ')}`);
                    }
                  };

                  let totalCountForProduct = 0;
                  let title = '';
                  productsForPrint[product.id] = {
                    ...product,
                    use: [],
                    firstDate: new Date(Number.MAX_SAFE_INTEGER),
                  };

                  product?.usages?.forEach(({ d1, d2, amount, act, assigneeUser }) => {
                    const hikersForAct = hikingData.hikers.filter((h) => {
                      let byStartDate = true;
                      let byFinishDate = true;
                      if (h.dateFrom) {
                        byStartDate = h.dateFrom <= d2;
                      }

                      if (h.dateTo) {
                        byFinishDate = h.dateTo >= d1;
                      }

                      return byStartDate && byFinishDate;
                    });

                    if (productsForPrint[product.id].firstDate > d1) {
                      productsForPrint[product.id].firstDate = d1;
                    }
                    productsForPrint[product.id].use.push({
                      d1,
                      d2,
                      amount,
                      act,
                      hikersForAct,
                      assigneeUser,
                    });
                    title += `${act.name} ${d1.toLocaleDateString()}\t${amount * hikersForAct.length}г. на ${hikersForAct.length}чел.\n${hikersForAct.map((h) => `${h.surname[0]}${h.name[0]} `)}\n\n`;
                    totalCountForProduct += amount * hikersForAct.length;
                  });

                  totalAmount += totalCountForProduct;

                  return (
                    <tr key={product.id}>
                      <td>
                        <PohRow className="d-flex align-items-center justify-content-between">
                          <PohCol sm={8} className="text-truncate text-nowrap">
                            {product.name}
                            <sup
                              title={product.usages
                                .map((u) =>
                                  [
                                    u.act.name.substr(0, 4),
                                    u.d1.toLocaleString(),
                                    `${u.amount}г.`,
                                    u.name,
                                  ].join('\t'),
                                )
                                .join('\n')}
                            >
                              {product.usages.length}
                            </sup>
                            {product.ex ? (
                              <sub className="text-muted"> ex. {product.ex.name}</sub>
                            ) : (
                              ''
                            )}
                          </PohCol>
                          <PohCol sm={4} className="d-flex align-items-center justify-content-end">
                            <PohAva
                              onClick={handleAssign}
                              width={24}
                              icon={<PersonFill />}
                              src={product.forcedUser ? product.forcedUser.photo : undefined}
                              alt={product.forcedUser ? product.forcedUser.name : undefined}
                              // iconName={product.forcedUser ? null : IconsEnum.user}
                              title={
                                product.idForce && product?.forcedUser?.name
                                  ? `Снять назначение с ${product.forcedUser.name}`
                                  : 'Назначить участнику'
                              }
                            />

                            {/*<PohButton size={ButtonSize.Small} className="ms-3 me-1" icon={IconsEnum.basket} />*/}
                            <PohButton
                              size={ButtonSize.Small}
                              icon={true}
                              className="ms-3 me-1"
                              onClick={() => {
                                showModal({
                                  title: product.name,
                                  size: 'lg',
                                  children: (
                                    <StickersBuiltIn
                                      id_hiking={id_hiking}
                                      id_product={product.ex?.id ?? product.id}
                                    />
                                  ),
                                });
                              }}
                            >
                              <Printer />
                            </PohButton>
                          </PohCol>
                        </PohRow>
                      </td>
                      <td className="text-end">{round(product.amount, 1)}</td>
                      <td className="text-end" title={title}>
                        {round(totalCountForProduct, 1) +
                          '/' +
                          round(product.amount * hikingData.hikers.length, 1)}
                        {allergyProducts[product.id] && (
                          <div className="text-start">
                            <PohAlert variant={AlertVariant.Danger} className="p-1">
                              ‼️ Аллергия ‼️
                              <small>
                                {allergyProducts[product.id].map((x) => {
                                  return (
                                    <li key={x.id} title={JSON.stringify(x, null, '  ')}>
                                      {[x.user.name, x.user.surname].join(' ')}: {x.comment}
                                    </li>
                                  );
                                })}
                              </small>
                            </PohAlert>
                          </div>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
              <tfoot>
                <tr>
                  <td className="text-end">Итого</td>
                  <td className="text-end text-danger">
                    {round(
                      products.reduce((sum, p) => sum + p.amount, 1),
                      0,
                    )}
                  </td>
                  <td className="text-end">
                    {totalAmount} /{' '}
                    {round(
                      products.reduce((sum, p) => sum + p.amount, 0) * hikingData.hikers.length,
                      1,
                    )}
                  </td>
                </tr>
              </tfoot>
            </table>
          )}
        </section>
      </PohContainer>
      {food && products && (
        <SummaryPanel foods={food} products={products} hikers={hikingData.hikers} />
      )}
      <aside style={{ position: 'fixed', top: 120, right: 0, gap: 8 }} className="p-2">
        <PohButton
          size={ButtonSize.Small}
          icon={true}
          title={'Матрица меню'}
          onClick={() => {
            open(`/hiking/${id_hiking}/menu/matrix`);
          }}
        >
          <Grid3X3 />
        </PohButton>
        <PohButton
          size={ButtonSize.Small}
          icon={true}
          title={'Дежурства'}
          onClick={() => {
            showModal({
              children: <DutyModal hikingData={hikingData} />,
            });
          }}
        >
          <CalendarRange />
        </PohButton>

        <PohButton
          size={ButtonSize.Small}
          icon={true}
          title={'Использование рецептов'}
          onClick={() => {
            showModal({
              header: 'Использование рецептов',
              children: <RecipesUsages recipesMetaMap={recipesMetaMap} />,
            });
          }}
        >
          <Reception3 />
        </PohButton>
      </aside>
    </>
  );
};

export default HikingMenu;
