import React from 'react';

import clsx from 'clsx';

import DayInfoWidget from '@apps/Hiking/one/components/DayInfoWidget';
import { showScheduleModal } from '@apps/Hiking/schedule/components/ScheduleModal/scheduleModalHelper';
import BGU from '@components/BGU/index';
import { round } from '@helpers/mathHelper';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row/index';
import PohProgress from '@ui-kit/Progress';

import {
  IHikingMenuActsByDays,
  IHikingMenuFoodWithAct,
} from '../../../../../@types/hikingMenu.types';

interface IDayFullHeaderProps {
  id_hiking: number;
  day: IHikingMenuActsByDays;
  food: IHikingMenuFoodWithAct[];
  dayNumber: number; //ind + 1
  additional?: React.ReactNode;
}

const DayFullHeader: React.FC<IDayFullHeaderProps> = ({
  id_hiking,
  day,
  dayNumber,
  food,
  additional,
}) => {
  const needKkal = day.acts.reduce(
    (acc, act) => acc + (act?.kkalCurrent || act?.kkalTarget || 0),
    0,
  );
  const fact = food
    .filter((x) => x.date.toLocaleDateString() === day.date.toLocaleDateString())
    .reduce(
      (acc, f) => ({
        energy: acc.energy + f.energy * f.correction,
        amount: acc.amount + f.amount * f.correction,
        proteins: acc.proteins + f.proteins * f.correction,
        fats: acc.fats + f.fats * f.correction,
        carbs: acc.carbs + f.carbs * f.correction,
      }),
      { energy: 0, amount: 0, proteins: 0, fats: 0, carbs: 0 },
    );

  const pct = round((fact.energy / needKkal) * 100, 0);
  const showDaySchedule = () =>
    showScheduleModal(id_hiking, day.date, `Расписание на ${day.date.toLocaleDateString()}`);

  return (
    <PohRow as="header" className="mb-2 bg-light p-2">
      <PohCol sm={10} className="d-flex align-items-center justify-content-between">
        <div
          className="d-flex align-items-center"
          onClick={showDaySchedule}
          title="Клик чтобы уивдеть расписание на этот день"
        >
          <h5>День&nbsp;{dayNumber}</h5>

          <DayInfoWidget date={day.date} className="ms-2 mb-1" />
          <span className="mx-2 px-2 border-start">{additional}</span>
        </div>
        <BGU
          portion={round(fact.amount, 0)}
          energy={round(fact.energy, 0)}
          protein={round(fact.proteins, 0)}
          fat={round(fact.fats, 0)}
          carbohydrates={round(fact.carbs, 0)}
          unit="в день на человека"
        />
      </PohCol>
      <PohCol sm={2} className="p-2 text-danger">
        <PohProgress
          value={pct}
          title={JSON.stringify({ ...fact, pct, needKkal }, null, '\t')}
          className={clsx({
            'bg-warning': pct < 80,
            'bg-success': pct >= 80,
            'bg-danger': pct > 110,
          })}
        >
          {pct}&thinsp;%
        </PohProgress>
      </PohCol>
    </PohRow>
  );
};

export default DayFullHeader;
