import React, { useContext } from 'react';

import PatchCheckFill from '@pohodnik/icons/svg/Badges/PatchCheckFill';
import PatchQuestion from '@pohodnik/icons/svg/Badges/PatchQuestion';
import Save from '@pohodnik/icons/svg/UI/Save';
import Save2Fill from '@pohodnik/icons/svg/UI/Save2Fill';
import clsx from 'clsx';

import { handleApiError } from '@helpers/httpClient';
import { err, success } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';
import { confirmModal } from '@ui-kit/Modal/index';

import { AuthContext } from '../../../../../contexts/AuthContext';
import {
  applyHikingMenuSaveAsync,
  deleteHikingMenuSaveAsync,
  getHikingMenuSavesAsync,
  renameHikingMenuSaveAsync,
  saveHikingMenuSaveAsync,
} from '../../../@services/hikingMenuSaves.service';
import { IHikingMenuSave } from '../../../@types/hiking.baseTypes';

interface IHikingMenuSavesProps {
  id_hiking: number;
  onApply: () => void;
  onConfirm?: (save: IHikingMenuSave) => void;
  disabled?: boolean;
  saves?: IHikingMenuSave[];
}

const HikingMenuSaves: React.FC<IHikingMenuSavesProps> = ({
  id_hiking,
  onApply,
  disabled = false,
  saves,
  onConfirm,
}) => {
  const [data, setData] = React.useState<IHikingMenuSave[]>([]);
  const [applying, setApplying] = React.useState<number | null>(null);
  const [isSaving, setIsSaving] = React.useState(false);
  const [isLoading, setIsLoading] = React.useState(true);

  const authContext = useContext(AuthContext);

  React.useEffect(() => {
    if (Array.isArray(saves)) {
      setData(saves);
      setIsLoading(false);
      return;
    }

    getHikingMenuSavesAsync(id_hiking)
      .then(setData)
      .finally(() => setIsLoading(false));
  }, [id_hiking, saves]);

  const handleApply = (id: number) => {
    setApplying(id);
    confirmModal({ children: 'Все несохраненные данные будут потеряны. Продолжить?' }).then(
      (isConfirm) => {
        if (isConfirm) {
          applyHikingMenuSaveAsync(id_hiking, id)
            .then((res) => {
              (res.success && success('Применено')) || (res.error && err(res.error));
              setData(
                data.map((x) =>
                  x.id === id ? { ...x, isCurrent: true } : { ...x, isCurrent: false },
                ),
              );
              onApply();
            })
            .catch((e) => err(e.message))
            .finally(() => setApplying(null));
        } else {
          setApplying(null);
        }
      },
    );
  };

  const handleSave = () => {
    setIsSaving(true);
    const name = prompt('Введите название для сборки');

    if (!name) {
      setIsSaving(false);
      return;
    }

    saveHikingMenuSaveAsync(id_hiking, name)
      .then(handleApiError)
      .then((res) => {
        if (!authContext.user) return;
        setData([
          {
            id: res.id,
            isCurrent: true,
            name,
            date: new Date(),
            userName: [authContext.user.name, authContext.user.surname].join(' '),
            confirmDate: null,
            confirmUser: null,
          },
          ...data.map((x) => ({ ...x, isCurrent: false })),
        ]);

        success('Сохранено');
      })
      .catch((e) => err(e?.message))
      .finally(() => setIsSaving(false));
  };

  const handleDelete = (id: number) => (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    confirmModal({ children: 'Удалить?', confirmText: 'Да' }).then((isConfirm) => {
      isConfirm &&
        deleteHikingMenuSaveAsync(id_hiking, id)
          .then(handleApiError)
          .then(() => {
            success('Удалено');
            setData(data.filter((x) => x.id !== id));
          })
          .catch((er) => err(er?.message));
    });
  };

  const handleRename = (id: number, oldName: string) => (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();

    const name = prompt('Введите название для сборки', oldName);

    if (!name) {
      return;
    }

    renameHikingMenuSaveAsync(id_hiking, id, name)
      .then(handleApiError)
      .then(() => {
        setData(data.map((x) => ({ ...x, name: x.id === id ? name : x.name })));
        success('Сохранено');
      })
      .catch((er) => err(er?.message));
  };

  const hasConfirmed = data.some((d) => d.confirmDate);

  return (
    <section className="mt-3 mb-4">
      <header className="d-flex align-items-center justify-content-between mb-2">
        <h4>Сохраненные сборки</h4>
        {!disabled && (
          <PohButton onClick={handleSave} disabled={isSaving} variant={ButtonVariant.Light}>
            Сохранить текущее меню как сборку {isSaving && <PohLoader />}
          </PohButton>
        )}
      </header>
      {isLoading ? (
        <PohLoader />
      ) : (
        <>
          {data?.length === 0 && <Empty height={20}>Нет сохраненных сборок</Empty>}
          {data?.length > 0 && (
            <PohList
              data={data.map((x) => ({
                key: x.id,
                action: true,
                content: (
                  <div className="d-flex align-items-center align-items-center justify-content-between">
                    <div
                      className="d-flex align-items-center"
                      title={[x.name, x.date.toLocaleString(), x.userName]
                        .filter(Boolean)
                        .join('\n')}
                    >
                      <div className="my-n2 ms-n2 me-2">
                        {applying && applying === x.id ? (
                          <PohLoader />
                        ) : (
                          <>{x.isCurrent ? <Save2Fill className="text-success" /> : <Save />}</>
                        )}
                      </div>
                      {+x.isCurrent === 1 ? (
                        <strong className={clsx('text-success')}>{x.name}</strong>
                      ) : (
                        x.name
                      )}
                    </div>
                    {
                      <div className="m-n2">
                        <span
                          title={
                            x.confirmDate
                              ? ['Утверждено', x.confirmDate.toLocaleString(), x.confirmUser].join(
                                  '\n',
                                )
                              : 'Ожидает утверждения'
                          }
                        >
                          {onConfirm ? (
                            (!hasConfirmed || x.confirmDate) && (
                              <PohButton
                                className="me-1"
                                icon={true}
                                onClick={(e) => {
                                  e.stopPropagation();
                                  onConfirm(x);
                                }}
                              >
                                {x.confirmDate ? (
                                  <PatchCheckFill className="text-success" />
                                ) : (
                                  <PatchQuestion className="text-muted" />
                                )}
                              </PohButton>
                            )
                          ) : x.confirmDate ? (
                            <PatchCheckFill className="text-success" />
                          ) : null}
                        </span>
                        {!disabled && !hasConfirmed && (
                          <PohButton
                            className="me-1"
                            icon={IconsEnum.edit}
                            onClick={handleRename(x.id, x.name)}
                          />
                        )}
                        {!disabled && !hasConfirmed && (
                          <PohButton icon={IconsEnum.trash} onClick={handleDelete(x.id)} />
                        )}
                      </div>
                    }
                  </div>
                ),
                onClick: () => !disabled && !hasConfirmed && !applying && handleApply(x.id),
                disabled: disabled,
              }))}
            />
          )}
        </>
      )}
    </section>
  );
};

export default HikingMenuSaves;
