import { IHikingMenuProductReplaceDto } from '../@types/DTO/hikingMenuReplaces.dto.types';
import { IHikingMenuProductReplace } from '../@types/hikingMenuReplaces.types';

export const mapHikingMenuProductReplaceToFront = (
  backData: IHikingMenuProductReplaceDto,
): IHikingMenuProductReplace => {
  return {
    id: +backData.id,

    rate: parseFloat(backData.rate),
    comment: backData.comment,

    sourceProduct: {
      id: +backData.id_source_product,
      name: backData.src_product_name,
      carbs: +backData.src_product_carbohydrates,
      protein: +backData.src_product_protein,
      fat: +backData.src_product_fat,
      energy: +backData.src_product_energy,
    },
    targetProduct: {
      id: +backData.id_target_product,
      name: backData.tgt_product_name,
      carbs: +backData.tgt_product_carbohydrates,
      protein: +backData.tgt_product_protein,
      fat: +backData.tgt_product_fat,
      energy: +backData.tgt_product_energy,
    },

    created: {
      date: new Date(backData.created_at),
      user: {
        id: +backData.creator_id,
        name: backData.creator_name,
        surname: backData.creator_surname,
        photo: backData.creator_photo,
      },
    },
  };
};
