import React from 'react';

import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohList from '@ui-kit/List';

interface IRecipesUsagesProps {
  recipesMetaMap: Record<number, Record<string, any>>;
}

const RecipesUsages: React.FC<IRecipesUsagesProps> = ({ recipesMetaMap }) => {
  return (
    <div>
      <h3>Использование блюд</h3>
      <PohList
        data={Object.entries(recipesMetaMap)
          .sort(([_, a], [__, b]) => b.usagesCount - a.usagesCount)
          .map(([id_recipe, meta]) => {
            return {
              key: id_recipe,
              content: (
                <div className="m-n1">
                  <PohBadge variant={BadgeVariant.Success} className="me-2">
                    {meta.usagesCount}
                  </PohBadge>
                  {meta.name}
                </div>
              ),
            };
          })}
      />
    </div>
  );
};

export default RecipesUsages;
