import React from 'react';

import { IProduct } from '@apps/Recipes/@types/recipes.types';
import { round } from '@helpers/mathHelper';

import BGU from '.';

interface IBGUForProductProps {
  product: IProduct;
  portion?: number;
  className?: string;
  unit?: string;
  rate?: number;
}

const BGUForProduct: React.FC<IBGUForProductProps> = ({
  product,
  portion = 100,
  unit = 'в порции',
  rate = 1,
  className,
}) => {
  return (
    <BGU
      portion={round(portion * rate, 0)}
      energy={round(product.energy * rate, 0)}
      protein={round(product.protein * rate, 0)}
      fat={round(product.fat * rate, 0)}
      carbohydrates={round(product.carbs * rate, 0)}
      unit={unit}
      className={className}
    />
  );
};

export default BGUForProduct;
