import React from 'react';

import ThreeDotsVertical from '@pohodnik/icons/svg/Controls/ThreeDotsVertical';
import clsx from 'clsx';

import BGU from '@components/BGU/index';
import { formattedLocaleTime } from '@helpers/dateHelper';
import { round } from '@helpers/mathHelper';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import PohCard from '@ui-kit/Card';
import PohDropdown from '@ui-kit/Dropdown';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row/index';
import PohLink from '@ui-kit/Link';
import PohProgress from '@ui-kit/Progress';

import { IFoodAct } from '../../../../../@types/hiking.baseTypes';
import { IHikingMenuFoodWithAct } from '../../../../../@types/hikingMenu.types';

/*
*                 handleAssignToHiker({
                    date: day.date.toISOString().substr(0,10),
                    id_act: +act.id
                }).catch(err);
                *
                *
                *
* */

interface IFoodActCardProps {
  act: IFoodAct;
  actFood: IHikingMenuFoodWithAct[];
  onHeaderDoubleClick: () => void;
  headerAdditional: React.ReactNode;
  bottomMenuActions: Record<string, () => void>;
  onFooterButtonClick: React.MouseEventHandler;
  disabled: boolean;
  children: React.ReactNode;
}

const FoodActCard: React.FC<IFoodActCardProps> = ({
  act,
  onHeaderDoubleClick,
  headerAdditional,
  actFood,
  bottomMenuActions,
  onFooterButtonClick,
  disabled = false,
  children,
}) => {
  const needKkalDayAct = act.kkalCurrent || act.kkalTarget || 0;
  const factDayAct = actFood.reduce(
    (acc, f) => ({
      energy: acc.energy + f.energy * f.correction,
      amount: acc.amount + f.amount * f.correction,
      proteins: acc.proteins + f.proteins * f.correction,
      fats: acc.fats + f.fats * f.correction,
      carbs: acc.carbs + f.carbs * f.correction,
    }),
    { energy: 0, amount: 0, proteins: 0, fats: 0, carbs: 0 },
  );

  const pctDayAct = round((factDayAct.energy / needKkalDayAct) * 100, 0);

  return (
    <PohCard
      bodyClassName="m-n3"
      header={
        <header onDoubleClick={onHeaderDoubleClick}>
          <PohRow>
            <PohCol sm={6}>
              <b>{act.name}</b>
              <sup>{formattedLocaleTime(act.start)}</sup>
              {act.is_self_sufficiency && (
                <small>
                  <small className="text-danger">Самообеспечение</small>
                </small>
              )}
              {headerAdditional}
            </PohCol>
            <PohCol sm={6} className="d-flex justify-content-end align-items-center">
              <BGU
                className="my-n2"
                portion={round(factDayAct.amount, 0)}
                energy={round(factDayAct.energy, 0)}
                protein={round(factDayAct.proteins, 0)}
                fat={round(factDayAct.fats, 0)}
                carbohydrates={round(factDayAct.carbs, 0)}
                unit={`${act.name} на человека`}
              />
            </PohCol>
          </PohRow>
        </header>
      }
      footerClassName="py-2"
      footer={
        !disabled && (
          <footer className="d-flex justify-content-between">
            <PohLink onClick={onFooterButtonClick}>Добавить</PohLink>

            <PohDropdown
              className="me-n2"
              onClick={(e) => e.stopPropagation()}
              menu={Object.entries(bottomMenuActions).map(([label, callback]) => {
                return (
                  <button
                    key={`bottom-level-menu-item-${label}`}
                    className="dropdown-item"
                    onClick={callback}
                    type="button"
                  >
                    {label}
                  </button>
                );
              })}
            >
              <PohButton size={ButtonSize.Small} icon={true}>
                <ThreeDotsVertical />
              </PohButton>
            </PohDropdown>
          </footer>
        )
      }
    >
      <PohProgress
        containerClassName="mt-n1"
        style={{ height: '2px' }}
        className={clsx({
          'bg-danger': pctDayAct < 50,
          'bg-warning': pctDayAct < 60,
          'bg-primary': pctDayAct > 70,
          'bg-success': pctDayAct >= 85,
        })}
        value={pctDayAct}
        title={[`${round(pctDayAct, 0)}%`, `${factDayAct.energy} из ${needKkalDayAct} ккал`].join(
          '\n',
        )}
      />
      {children}
    </PohCard>
  );
};

export default FoodActCard;
